import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t, address actor) public {
        vm.assume(t > 0);
        vm.assume(actor != address(0) && actor != address(c));
        uint256 amt = 10 ether;
        vm.deal(actor, 2 * amt);

        // first successful call at timestamp t
        vm.warp(t);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amt}("");
        assertTrue(ok1, "first call at t should succeed");

        // second call at the SAME timestamp t must revert:
        // require(block.timestamp > pastBlockTime) with pastBlockTime == t
        vm.roll(block.number + 1); // satisfy block-number state, timestamp unchanged
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amt}("");
        assertTrue(!ok2, "second call at same timestamp must revert");
    }
}

