pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address actor = address(0xA11CE);

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts1, uint256 ts2) public {
        // admissible: first call at ts1 succeeds; second call at ts2 is after the
        // first call's block number but no later than its timestamp
        vm.assume(ts1 >= block.number + 2);
        vm.assume(ts2 > block.number);
        vm.assume(ts2 <= ts1);

        vm.deal(actor, 10 ether);

        // first call at timestamp ts1
        vm.warp(ts1);
        vm.prank(actor);
        bool firstOk;
        try c.fallback{value: 10 ether}() { firstOk = true; } catch { firstOk = false; }
        assertTrue(firstOk, "first call should succeed");

        // second call in a block whose timestamp lies in (block.number, ts1]
        vm.warp(ts2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool secondOk;
        try c.fallback{value: 10 ether}() { secondOk = true; } catch { secondOk = false; }

        // reference: guard stored ts1, so ts2 <= ts1 must revert
        assertTrue(!secondOk, "second call in same-or-earlier timestamp must revert");
    }
}

