        Reverter actor = new Reverter();
        ts = bound(ts, 1, type(uint256).max);
        vm.warp(ts);
        blockNum = bound(blockNum, block.number + 1, type(uint256).max - 1);
        vm.roll(blockNum);

        uint256 amount = 10 ether;
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: with a reverting receiver, the call must revert precisely
